        return {"stdout": "", "code": 0, "files": {}, "stderr": "", "hits": hits, "missing": bool(need and not re.search(need, text))}
    d = tempfile.mkdtemp(prefix="chk-")
    try:
        for p, t in sorted(c.get("files", {}).items()):
            fp = os.path.join(d, p)
